insert into public.knowledge_test_items (item_no, question, choices, correct_index, explanation, is_active)
values
(1, 'ก่อนให้ High-Alert Drug ควรทำ Double Check อย่างไร?', '["ตรวจคนเดียว","ตรวจร่วมกับพยาบาลอีก 1 คน","ตรวจหลังให้ยา","ไม่ต้องตรวจ"]'::jsonb, 1, 'ยาความเสี่ยงสูงควรมีการ Double Check ตามแนวทางความปลอดภัยของหน่วยงาน', true),
(2, 'การยืนยันตัวผู้ป่วยก่อนให้ยาควรใช้กี่ตัวบ่งชี้อย่างน้อย?', '["1","2","3","ไม่จำเป็น"]'::jsonb, 1, 'ควรยืนยันอย่างน้อย 2 ตัวบ่งชี้', true),
(3, 'ข้อใดถูกต้องเกี่ยวกับการให้สารน้ำด้วยเครื่องควบคุม?', '["ปล่อย Free Flow ได้","ไม่ปล่อย Free Flow และใช้เครื่องควบคุมตามข้อกำหนด","ใช้เฉพาะเมื่อมีญาติ","ไม่ต้องตรวจอัตรา"]'::jsonb, 1, 'หนึ่งใน critical behaviors คือใช้เครื่องควบคุมและไม่ปล่อย Free Flow', true),
(4, 'ฉลาก High-Alert Drug ควรมีข้อมูลสำคัญใด?', '["ชื่อผู้ป่วยอย่างเดียว","ชื่อยาและความเข้มข้น","สีของถุงยา","ชื่อเวรเท่านั้น"]'::jsonb, 1, 'ฉลากควรระบุข้อมูลยาที่สำคัญต่อการตรวจสอบและความปลอดภัย', true),
(5, 'เมื่อพบอาการผิดปกติจากยา ควรดำเนินการอย่างไร?', '["รอดูอาการเสมอ","หยุดยา/ช่วยเหลือเบื้องต้นและรายงานแพทย์ทันทีตามข้อบ่งชี้","รอเวรถัดไป","ไม่ต้องบันทึก"]'::jsonb, 1, 'การตอบสนองต่ออาการผิดปกติอย่างรวดเร็วเป็นพฤติกรรมสำคัญด้านความปลอดภัย', true),
(6, 'ข้อใดควรตรวจสอบก่อนใช้ยาและสารน้ำ?', '["วันหมดอายุ","สีฉลากอย่างเดียว","ชื่อเวร","จำนวนญาติ"]'::jsonb, 0, 'ต้องตรวจสอบวันหมดอายุของยาและสารน้ำก่อนใช้', true),
(7, 'การบันทึก MAR มีความสำคัญอย่างไร?', '["ไม่เกี่ยวกับความปลอดภัย","เป็นหลักฐานการให้ยาและช่วยป้องกันการให้ยาซ้ำ/ตกหล่น","ใช้เฉพาะฝ่ายการเงิน","ทำเมื่อสิ้นเดือน"]'::jsonb, 1, 'MAR เป็นส่วนสำคัญของ medication administration safety', true),
(8, 'ควรประเมิน IV site เพื่อป้องกันภาวะแทรกซ้อนใด?', '["Extravasation","สายตาพร่ามัว","ไข้จากอากาศ","หูอื้อ"]'::jsonb, 0, 'ควรตรวจตำแหน่ง IV site อย่างสม่ำเสมอเพื่อป้องกัน Extravasation', true),
(9, 'Near Miss ควรจัดการอย่างไร?', '["ไม่ต้องรายงานเพราะไม่มีอันตราย","รายงานตามระบบของหน่วยงาน","ลบทิ้งจากบันทึก","แจ้งเฉพาะเพื่อนร่วมงาน"]'::jsonb, 1, 'Near Miss เป็นข้อมูลสำคัญเพื่อป้องกันเหตุซ้ำและควรรายงานตามระบบ', true),
(10, 'การคำนวณขนาดยา/ความเข้มข้น/อัตราการให้ High-Alert Drug ควรเป็นอย่างไร?', '["ตรวจครั้งเดียวก็พอ","คำนวณและตรวจสอบให้ถูกต้องตามแนวทาง รวมถึง Double Check เมื่อกำหนด","เดาได้หากคุ้นเคย","ให้ผู้ป่วยคำนวณ"]'::jsonb, 1, 'การคำนวณยาความเสี่ยงสูงต้องถูกต้องและตรวจสอบตามแนวทาง', true)
